    for fc in f['faces']: a[fc['tag']] += ((fc['p'][1][0] - fc['p'][0][0]) ** 2 + (fc['p'][1][1] - fc['p'][0][1]) ** 2) ** 0.5 * (fc['z'][1] - fc['z'][0])
